import type { AvatarStackProps } from "./avatar-stack.types";

import React, { forwardRef } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import Avatar from "@components/avatar/avatar";

import { AvatarStackClasses, StyledAvatarStack } from "./avatar-stack.styles";

const AvatarStack = forwardRef(
  (
    { className, variant = "default", children, ring, size, ...props }: AvatarStackProps,
    ref: React.ForwardedRef<null>,
  ) => {
    const appliedSize = size ?? "lg";
    const theme = useTheme(),
      rootClasses = clsx(
        AvatarStackClasses.root,
        {
          [AvatarStackClasses[appliedSize as keyof typeof AvatarStackClasses]]: appliedSize,
        },
        className,
      );

    return (
      <StyledAvatarStack
        ref={ref}
        className={rootClasses}
        currentTheme={theme}
        role="group"
        variant={variant}
        {...props}
      >
        {React.Children.map(children, (child) => {
          if (!React.isValidElement(child)) return child;
          if (child.type === Avatar) {
            return React.cloneElement(child, {
              ring,
              size,
              variant,
              ...child.props,
            });
          }
          return child;
        })}
      </StyledAvatarStack>
    );
  },
);

AvatarStack.displayName = "AvatarStack";

export default AvatarStack;
